\label{CorFree}
    Consider the free group $\mathbf{F}_r$ on $r$ generators with $r \in \{2, 3, \dots, \infty\}$:
    \begin{enumerate}[label={\rm \textbf{(\roman*)}}, ref={(\roman*)}]
        \item \label{itm:CorFree1}
        \textbf{Free balls.} The Herz-Schur multipliers $H_{m_R}$ are uniformly cb-bounded
        \[
            \sup_{R>0} 
            \big\| H_{m_R} \colon S_p(\mathbf{F}_r) \to S_p(\mathbf{F}_r) \big\|_\mathrm{cb} 
            \lesssim p_\ast^3 \quad \text{for every} \quad 1 < p < \infty.
        \]
        However, the Fourier multipliers $T_{m_R} \colon L_p(\mathcal{L} \mathbf{F}_r) \to L_p(\mathcal{L} \mathbf{F}_r)$ are not uniformly bounded when $|\frac1p - \frac12| > \frac16$.

        \item \label{itm:CorFree2}
        \textbf{Free horoballs.} Given $\rho \in \partial \mathbf{F}_r$, the Herz-Schur multiplier
        $H_{m_\rho} \colon S_p(\mathbf{F}_r) \to S_p(\mathbf{F}_r)$ is cb-bounded. However, $T_{m_\rho} \colon L_p(\mathcal{L}\mathbf{F}_r) \to L_p(\mathcal{L}\mathbf{F}_r)$ is unbounded for $|\frac1p - \frac12| > \frac16$. 
    \end{enumerate}

\label{CorSimple}
    The following results hold for $1 < p \neq 2 < \infty \hskip-1pt \colon$
    \begin{enumerate}[label={\rm \textbf{(\roman*)}}, ref={{(\roman*)}}]
        \item \label{itm:CorSimple1} 
        \textbf{Explicit multipliers in $\mathrm{G} = \mathrm{PGL}_2(\mathbf{Q}_q)$.} Let $z \in \mathbf{T} \setminus \{\pm 1\}$ and $m_z(g) = z^{\ell_\mathrm{Car}(g)}$. Then $m_z$ is $\mathrm{K} = \mathrm{PGL}_2(\mathbf{Z}_p)$-biinvariant, its Herz-Schur multiplier $H_{m_z}$is completely bounded on the Schatten $p$-class $S_p(\mathrm{G})$, while $T_{m_z}$ is unbounded on $L_p(\mathcal{L} \mathrm{G})$ as a Fourier multiplier. 

        \item \label{itm:CorSimple2}
        \textbf{Cocycle amplification in $\mathrm{G} = \mathrm{PSL}_2(\mathbf{R})$ of phase shifts.} Let $z \in \mathbf{T}$ and ${\widehat{m}_z}$ be the cocycle amplification above. Then $\widehat{m}_z$ is $\mathrm{PSO}(2)$-biinvariant, the family of Herz-Schur multipliers $H_{\widehat{m}_z}$ are uniformly completely bounded on $S_p(\mathrm{G})$, while 
        \[
            \sup_{|z|=1} \big\| T_{\widehat{m}_z}\colon L_p(\mathcal{L} \mathrm{G}) \to L_p(\mathcal{L} \mathrm{G}) \big\| = \infty.
        \] 
    \end{enumerate}

\label{HoroballvsBall}
    Given $\rho \in \partial \mathbf{F}_r$ and $p \neq 2$, the following are equivalent:
    \begin{enumerate}[label={\rm \textbf{(\roman*)}}, ref={(\roman*)}]
        \item \label{itm:HoroballvsBall.1} $\displaystyle \big\| T_{m_\rho} \colon L_p(\mathcal{L} \mathbf{F}_r) \to L_p(\mathcal{L} \mathbf{F}_r) \big\| < \infty$.
        \item \label{itm:HoroballvsBall.2} $\displaystyle \sup_{R > 0} \big\| T_{\1_{B_R}} \colon L_p(\mathcal{L} \mathbf{F}_r) \to L_p(\mathcal{L} \mathbf{F}_r) \big\| < \infty$. 
    \end{enumerate}

\label{prop:generating}
    For $|u|<1$ and $s\in[-1,1]$, we have
    \begin{equation}
        \label{eq:Gformula}
        \mathcal{G}_u(s) := \sum_{n=0}^{\infty}u^n Q_n(s)
         =
         \frac{1+2(\sqrt{\tau}-1)su+(1-\frac1{\sqrt{\tau}})u^2}{1-2su+u^2}.
    \end{equation}
    For $|u|=1$, \eqref{eq:Gformula} still makes sense by means of Abel summation.
Moreover, we get    
\begin{enumerate}[label={\rm \textbf{(\roman*)}}, ref={(\roman*)}]
        \item \label{itm:pNorm1} If $\alpha \in (0,\pi)$ and $\beta \in (0,1)$ then
        \begin{equation}\label{eq:interior-asymptotics}
            \| \mathcal{G}_{\beta e^{i \alpha}} \|_p
            \simeq_{(r,p,\alpha)}
            \begin{cases}
                \log\!\dfrac1{1-\beta},& \text{ when } p=1,\\[4mm]
                (1-\beta)^{\frac1{p}-1},& \text{ when } 1<p\leq\infty.
            \end{cases}
        \end{equation}

        \item \label{itm:pNorm2} Similarly, if $\alpha = 0$ and $\beta \in (0,1)$, it holds that
        \begin{equation}
            \label{eq:endpoint-asymptotics}
            \|\mathcal{G}_{\beta} \|_p
            \simeq_{(r,p)}
            \begin{cases}
                1, & \text{ when } 1\leq p<\dfrac{3}{2},\\[3mm]
                \Big( \log\!\dfrac1{1-\beta} \Big)^{\frac{2}{3}},& \text{ when } p=\dfrac32,\\[4mm]
                (1-\beta)^{\frac{3}{p}-2},& \text{ when } \dfrac32<p\leq \infty,
            \end{cases}
        \end{equation}
    \end{enumerate}

\label{ThmBallsSL2}
    Consider the symbols $m_s \colon \mathrm{PSL}_2(\mathbf{R}) \to \mathbf{C}$ given by $m_s(g) = e^{2 \pi i s L(g)}$ for any $s \in \mathbf{R}$. 
    The family of Herz-Schur multipliers $\{H_{m_s} \colon s \in \mathbf{R}\}$ is not uniformly bounded on $S_p$. In other words
    \begin{equation}
        \label{eq:NonUniformSL2}
        \sup_{s \in \mathbf{R}} \big\| H_{m_s} \colon S_p(\mathrm{PSL}_2(\mathbf{R})) \to S_p(\mathrm{PSL}_2(\mathbf{R})) \big\| = \infty \quad \text{for every} \quad p \neq 2.
    \end{equation}

\label{prp:cocycleWeakLaw}
    The following holds in $\mu$-probability 
    \begin{equation} \nonumber
        \lim_{t \to \infty} \frac{\ell_T \big( \beta( \, \cdot \, , a_t ) \big)}{t \log t} = \frac{12}{\pi^2} 
    \end{equation}
    for any cocycle $\beta: \Omega \times \mathrm{G} \to \Gamma$ associated to a measurable cross section of the quotient $\Gamma \backslash \mathrm{G}$. As a consequence, the following limit holds for every $s \in \mathbf{R}$ and any sequence $(R_j)_{j \ge 1}$ with $R_j \to \infty$ as $j \to \infty$
    \begin{equation} \nonumber
        \lim_{j \to \infty} \widehat{m}_{z_j}(a_{R_j s}) = e^{i s}
        \quad \text{where} \quad z_j = e^{i \tfrac{\pi^2}{12 \, R_j \log R_j}}. 
    \end{equation}

\label{lem:spherical-limit}
    There is a constant $C > 0$ such that
    \begin{enumerate}[label={\rm \textbf{(\roman*)}}, ref={\rm (\roman*)}]
        \item \label{pslphase:eq:phi-bound}
        $|\varphi_\lambda(t)|\leq\varphi_0(t) \leq C(1+t)e^{-t/2}$ for every $\lambda, t\geq0$. 
        \item \label{pslphase:eq:phi-limit} 
        $\displaystyle{\lim_{R\to\infty} \tfrac{1}{R} e^{\frac{R s}{2}} \varphi_{\frac{\xi}{R}}(Rs) = \frac{2\sin(\xi s)}{\pi\xi}}$ for every $s>0$ and $\xi\geq0$.
    \end{enumerate}

\label{lem:U-convergence}
    Let $\{ h_j \colon \mathrm{G} \to \mathbf{C} \mid j \ge 1 \}$ be a uniformly bounded sequence of $\mathrm{K}$-biinvariant functions. Assume there are scalars $R_j \to \infty$ such that $\lim_{j} h_j(a_{R_j s}) = \Phi(s)$ for some funcion $\Phi \in L_\infty(\mathbf{R}_+)$. Taking $M_\Phi(f) = \Phi f$, let $B_\Phi := U^{-1}_\infty M_{\Phi} U_\infty$ be the spectral multiplier associated to the unitary $U_\infty$. Then, the following properties hold: 
    \begin{enumerate}[label={\rm \textbf{(\roman*)}}, ref={\rm {(\roman*)}}]
        \item \label{itm:U-convergence1} For every $F \in C_c^\infty(\mathbf{R}_+)$, $U_jF\longrightarrow U_\infty F$ in $L_2(ds)$-norm.
        \item \label{itm:U-convergence2} For every $F, G \in C_c^\infty(\mathbf{R}_+)$, we have $\displaystyle{\langle \Lambda_j F, G\rangle \to \langle B_\Phi F, G\rangle}$.
    \end{enumerate}

