\label{rmk:ReturnTime}
The map $\mathcal{R}$ on the last item admits a very natural geometric interpretation. Indeed, if we consider the embedding $\iota \colon \Sigma \to \Gamma \backslash \mathrm{G}$, its image $\mathscr{Cs} = \iota[\Sigma]$ is a two-dimensional subset composed of two sheets. Now, take the right action of the one-parameter group $t \mapsto a_t$ inside $\mathrm{G}$ defined in \eqref{eq:defAgroup}. Clearly, it induces a flow $\phi_t \colon \Gamma \backslash \mathrm{G} \to \Gamma \backslash \mathrm{G}$ given by $\phi_t(\Gamma g) = \Gamma g a_t$. If $\zeta = (x,y, \varepsilon) \in \Sigma$ are the coordinates of a point in $\iota(\zeta) \in \mathscr{Cs}$, the map $\mathcal{R}$ describes the coordinates on $\mathscr{Cs}$ of the first point of the flow $t \mapsto \phi_t(\iota(\zeta))$ that returns to $\mathscr{Cs}$, while the return time is given by $r(x) = -2 \log x$. In other words, we have the identity $\phi_{r(x)}(\iota(\zeta)) = \iota(\mathcal{R}(\zeta))$. This justifies why the parametrization of $\Omega$ contains $\mathscr{Cs}$ and an extra variable in $[0,-2\log x]$.

\label{lem:return-cocycle}
	The following identities hold a.e. 
	\begin{equation*} 
		\beta_0(z,a_t)
		=
		\prod_{1 \le j \le n_t(z)}^{\rightarrow}
		W_{\varepsilon+j-1\ ({\rm mod}\ 2)}
		\left( d_j \right) 
        \qquad \text{and} \qquad
        \ell_T(\beta_0(z,a_t))
		=
		2\sum_{j=1}^{n_t(z)} d_j,
	\end{equation*}
	The product arrow $\rightarrow$ means that the factors are ordered from left to right in increasing order of \(j\).

Note that 
	\[
	\begin{bmatrix}
		1& d_{j+1}\\
		0&1
	\end{bmatrix}^{-1}
	=
	(b^2a)^{d_{j+1}}
	=
	W_0(d_{j+1}),\quad 	
    \begin{bmatrix}
		1 & 0\\
		d_{j+1} &1
	\end{bmatrix}^{-1}
	=
	(ba)^{d_{j+1}}
	=
	W_1\left(d_{j+1}\right).
	\]
	A straightforward matrix calculation yields that
	\begin{equation*} 
		s_{\varepsilon_j}(x_j,y_j)\,a_{\tau_j}
		=
		W_{\varepsilon_{j}}
		\left(d_{j+1}\right)
		s_{\varepsilon_{j+1}}(x_{j+1},y_{j+1})
        \quad \text{ for every } j \geq 0.
	\end{equation*}
	By iteration, we obtain that 
	\[
		s_\varepsilon(x,y)\,a_{S_{n}}
		=
		\bigg[
		\prod_{1 \le j \le n}^{\rightarrow}
		W_{\varepsilon+j-1\ ({\rm mod}\ 2)}
		\left(
		d_j
		\right)
		\bigg]
		s_{\varepsilon_n}(x_n,y_n),
    \]
    where again $S_{n} = \sum_{j=0}^{n-1}\tau_j$. In particular
	\begin{equation}
        \label{eq:iterated-return-cocycle} 
        s_\varepsilon(x,y)a_{u+t}
        = 
        \bigg[
            \prod_{1 \le j \le n}^{\rightarrow}
            W_{\varepsilon+j-1\ ({\rm mod}\ 2)}
            \left(d_j\right)
	    \bigg]
        s_{\varepsilon_n}(x_n,y_n) a_{u+t-S_{n}}. 	
    \end{equation}
	By definition, we have $0 \leq  u+t-\sum_{j=0}^{n-1}\tau_j < \tau_n$ for $n=n_t(z)$ and hence the element after the bracketed product in \eqref{eq:iterated-return-cocycle} belongs to the fundamental domain in Lemma \ref{lem:arnoux-fd},
	which in particular yields that  
	\begin{equation}
        \label{eq:representative-after-flow}
		\sigma_0(za_t)
		= \sigma_0(\Gamma s_\varepsilon(x,y)a_{u+t} ) =
		s_{\varepsilon_n}(x_n,y_n)
		a_{u+t-S_{n}}.
	\end{equation}
	Note that $\sigma_0(z)a_t
	=
	s_\varepsilon(x,y)a_{u+t}$. So together with 
	\eqref{eq:iterated-return-cocycle} and definition of the cocycle $\beta_0$, we obtain the first identity of the lemma.
	Moreover, the last assertion immediately follows from identity \eqref{Eq-nB} 
	\[
	\ell_T(\beta_0(z,a_t))
	=
	2n_\mathrm{B}(\beta_0(z,a_t))
	=
	2\sum_{j=1}^{n_t(z)}
	d_j. \qedhere
	\]

\label{lem:khintchine}
	The functions $d_j = d_j(x)$ satisfy that
	\begin{equation}\label{eq:khintchine-weak-law}
		\frac{1}{n\log n}
		\sum_{j=1}^{n}
		d_j
        \,
		\longrightarrow
        \, 
        \frac1{\log2}
	\end{equation}
	in probability as $n \to \infty$ with respect to the Lebesgue measure on the unit interval $(0,1)$.
